/**
 * Login Component (Standalone)
 */

import { Component, OnInit, ViewChild, ElementRef } from '@angular/core';
import {
  FormBuilder,
  FormGroup,
  ReactiveFormsModule,
  Validators,
  FormsModule,
} from '@angular/forms';
import { Router, RouterLink } from '@angular/router';
import { CommonModule } from '@angular/common';
import { AuthService } from '@core/services/auth.service';
import { environment } from '@env/environment';

declare var google: any;

@Component({
  selector: 'app-login',
  standalone: true,
  imports: [CommonModule, ReactiveFormsModule, FormsModule, RouterLink],
  template: `
    <div class="login-container">
      <div class="login-card">
        <h1>CodeRank</h1>
        <h2>Login</h2>

        <form
          [formGroup]="loginForm"
          (ngSubmit)="onSubmit()"
        >
          <div class="form-group">
            <label for="email">Email</label>
            <input
              type="email"
              id="email"
              formControlName="email"
              placeholder="Enter your email"
            />
            <span
              class="error"
              *ngIf="loginForm.get('email')?.hasError('required')"
            >
              Email is required
            </span>
          </div>

          <div class="form-group">
            <label for="password">Password</label>
            <input
              type="password"
              id="password"
              formControlName="password"
              placeholder="Enter your password"
            />
            <span
              class="error"
              *ngIf="loginForm.get('password')?.hasError('required')"
            >
              Password is required
            </span>
          </div>

          <button
            type="submit"
            [disabled]="!loginForm.valid || loading"
          >
            {{ loading ? 'Logging in...' : 'Login' }}
          </button>

          <p
            class="error"
            *ngIf="error"
          >
            {{ error }}
          </p>
        </form>

        <div class="divider">
          <span>OR</span>
        </div>

        <!-- Google Sign-In Button -->
        <div
          #googleSignInButton
          class="google-signin-container"
        ></div>

        <p class="signup-link">Don't have an account? <a routerLink="/auth/register">Sign up</a></p>
      </div>
    </div>
  `,
  styles: [
    `
      .login-container {
        display: flex;
        justify-content: center;
        align-items: center;
        min-height: 100vh;
        background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
      }

      .login-card {
        background: white;
        padding: 40px;
        border-radius: 10px;
        box-shadow: 0 10px 25px rgba(0, 0, 0, 0.2);
        width: 100%;
        max-width: 400px;
      }

      h1 {
        color: #667eea;
        text-align: center;
        margin-bottom: 10px;
      }

      h2 {
        color: #333;
        text-align: center;
        margin-bottom: 30px;
      }

      .form-group {
        margin-bottom: 20px;
      }

      label {
        display: block;
        margin-bottom: 8px;
        color: #333;
        font-weight: 500;
      }

      input {
        width: 100%;
        padding: 10px;
        border: 1px solid #ddd;
        border-radius: 5px;
        font-size: 14px;
        box-sizing: border-box;
      }

      input:focus {
        outline: none;
        border-color: #667eea;
        box-shadow: 0 0 0 3px rgba(102, 126, 234, 0.1);
      }

      button {
        width: 100%;
        padding: 12px;
        background: #667eea;
        color: white;
        border: none;
        border-radius: 5px;
        font-size: 16px;
        font-weight: 600;
        cursor: pointer;
        transition: background 0.3s;
      }

      button:hover:not(:disabled) {
        background: #5568d3;
      }

      button:disabled {
        background: #ccc;
        cursor: not-allowed;
      }

      .error {
        color: #e74c3c;
        font-size: 12px;
        margin-top: 5px;
      }

      .divider {
        display: flex;
        align-items: center;
        margin: 25px 0 20px;
        color: #999;
        font-size: 12px;
      }

      .divider::before,
      .divider::after {
        content: '';
        flex: 1;
        height: 1px;
        background: #ddd;
      }

      .divider span {
        padding: 0 10px;
      }

      .google-signin-container {
        display: flex;
        justify-content: center;
        margin: 20px 0;
      }

      .signup-link {
        text-align: center;
        margin-top: 20px;
        color: #666;
      }

      .signup-link a {
        color: #667eea;
        text-decoration: none;
        font-weight: 600;
      }

      .signup-link a:hover {
        text-decoration: underline;
      }
    `,
  ],
})
export class LoginComponent implements OnInit {
  @ViewChild('googleSignInButton') googleSignInButton!: ElementRef;

  loginForm!: FormGroup;
  loading = false;
  error = '';

  constructor(
    private formBuilder: FormBuilder,
    private authService: AuthService,
    private router: Router
  ) {}

  ngOnInit(): void {
    this.initializeForm();
    this.initializeGoogleSignIn();
  }

  initializeForm(): void {
    this.loginForm = this.formBuilder.group({
      email: ['', [Validators.required, Validators.email]],
      password: ['', [Validators.required, Validators.minLength(6)]],
    });
  }

  initializeGoogleSignIn(): void {
    // Wait for Google API to load
    if (typeof google !== 'undefined') {
      setTimeout(() => {
        google.accounts.id.initialize({
          client_id: environment.googleClientId,
          callback: (response: any) => this.handleGoogleSignIn(response),
        });

        google.accounts.id.renderButton(this.googleSignInButton?.nativeElement, {
          theme: 'outline',
          size: 'large',
        });
      }, 100);
    }
  }

  handleGoogleSignIn(response: any): void {
    if (!response.credential) {
      this.error = 'Google sign-in failed';
      return;
    }

    this.loading = true;
    this.error = '';

    this.authService.googleLogin(response.credential).subscribe({
      next: () => {
        // Use setTimeout to ensure auth state is fully updated before navigation
        setTimeout(() => {
          this.router.navigate(['/dashboard/editor']);
        }, 100);
      },
      error: (error: any) => {
        if (error.error?.message) {
          this.error = error.error.message;
        } else if (error.error?.error?.message) {
          this.error = error.error.error.message;
        } else if (typeof error.error === 'string') {
          this.error = error.error;
        } else {
          this.error = 'Google sign-in failed. Please try again.';
        }
        this.loading = false;
      },
    });
  }

  onSubmit(): void {
    if (!this.loginForm.valid) return;

    this.loading = true;
    this.error = '';
    const { email, password } = this.loginForm.value;

    this.authService.login(email, password).subscribe({
      next: () => {
        this.router.navigate(['/dashboard/editor']);
      },
      error: (error: any) => {
        if (error.error?.message) {
          this.error = error.error.message;
        } else if (error.error?.error?.message) {
          this.error = error.error.error.message;
        } else if (typeof error.error === 'string') {
          this.error = error.error;
        } else {
          this.error = 'Login failed. Please try again.';
        }
        this.loading = false;
      },
    });
  }
}
